import java.util.*;

class Solution {
    public boolean isSymmetric(TreeNode root) {
        if (root == null) return true;

        // 必须用允许 null 的队列：这里要把空孩子也放进队列占位
        Deque<TreeNode> queue = new LinkedList<>();
        queue.offer(root);

        while (!queue.isEmpty()) {
            int size = queue.size();
            List<Integer> level = new ArrayList<>();
            for (int i = 0; i < size; i++) {
                TreeNode node = queue.poll();
                if (node == null) {
                    level.add(null);   // 必须记录 null 保留结构信息
                    continue;
                }
                level.add(node.val);
                queue.offer(node.left);
                queue.offer(node.right);
            }
            // 判本层回文
            int l = 0, r = level.size() - 1;
            while (l < r) {
                Integer a = level.get(l), b = level.get(r);
                if (a == null && b == null) { l++; r--; continue; }
                if (a == null || b == null || !a.equals(b)) return false;
                l++; r--;
            }
        }
        return true;
    }
}

class Solution {
    public boolean isSymmetric(TreeNode root) {
        return root == null || mirror(root.left, root.right);
    }

    private boolean mirror(TreeNode a, TreeNode b) {
        if (a == null && b == null) return true;    // 顺序不能颠倒
        if (a == null || b == null) return false;
        if (a.val != b.val) return false;
        // 交叉比较：a 的左边对 b 的右边
        return mirror(a.left, b.right) && mirror(a.right, b.left);
    }
}

import java.util.*;

class Solution {
    public boolean isSymmetric(TreeNode root) {
        if (root == null) return true;

        // LinkedList 允许 null，ArrayDeque 不允许
        Deque<TreeNode> queue = new LinkedList<>();
        queue.offer(root.left);
        queue.offer(root.right);

        while (queue.size() >= 2) {
            TreeNode a = queue.poll();
            TreeNode b = queue.poll();

            if (a == null && b == null) continue;
            if (a == null || b == null) return false;
            if (a.val != b.val) return false;

            // 交叉入队，对应递归的 mirror(a.left, b.right) && mirror(a.right, b.left)
            queue.offer(a.left);
            queue.offer(b.right);
            queue.offer(a.right);
            queue.offer(b.left);
        }
        return true;
    }
}
